import{_ as t,c as a,o as s,ag as i}from"./chunks/framework.B-aGGnuW.js";const k=JSON.parse('{"title":"Install a desktop","description":"","frontmatter":{},"headers":[],"relativePath":"installation/install-desktop.md","filePath":"installation/install-desktop.md","lastUpdated":1792149212000}'),n={name:"installation/install-desktop.md"};function r(l,e,d,o,h,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="install-a-desktop" tabindex="-1">Install a desktop <a class="header-anchor" href="#install-a-desktop" aria-label="Permalink to &quot;Install a desktop&quot;">​</a></h1><p>Choose one desktop and one display manager. These commands still run inside the chroot; enable services here without <code>--now</code>. They start after reboot. If your GPU needs a legacy AUR driver, install the desktop packages but skip enabling its display manager until you have followed the <a href="/installation/useful-packages#nvidia">NVIDIA instructions</a>.</p><h2 id="kde-plasma" tabindex="-1">KDE Plasma <a class="header-anchor" href="#kde-plasma" aria-label="Permalink to &quot;KDE Plasma&quot;">​</a></h2><p>Plasma is the main desktop used in this guide. <a href="https://kde.org/announcements/plasma/6/6.8.0/" target="_blank" rel="noreferrer">Plasma 6.8</a> uses Wayland; X11 applications run through Xwayland.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plasma</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> konsole</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dolphin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ark</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gwenview</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> okular</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xorg-xwayland</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plasmalogin.service</span></span></code></pre></div><p>The <code>plasma</code> group includes <a href="https://wiki.archlinux.org/title/Plasma_Login_Manager" target="_blank" rel="noreferrer">Plasma Login Manager</a>. Accept the group selection to install it. SDDM is an alternative; if choosing it, install <code>sddm</code> and enable <code>sddm.service</code> instead. Enable only one login service.</p><p>Optional applications include <code>kcalc</code>, <code>filelight</code>, <code>kdegraphics-thumbnailers</code>, <code>ffmpegthumbs</code> and <code>kdeconnect</code>. Install <code>sshfs</code> if you need KDE Connect&#39;s filesystem browsing.</p><p>See <a href="https://wiki.archlinux.org/title/KDE" target="_blank" rel="noreferrer">KDE</a> for session and hardware troubleshooting.</p><h2 id="other-desktops" tabindex="-1">Other desktops <a class="header-anchor" href="#other-desktops" aria-label="Permalink to &quot;Other desktops&quot;">​</a></h2><p>Install only the row you choose. The display manager column identifies the additional package and service to enable. Consult the linked desktop page for session-specific setup; Wayland support varies between desktops.</p><table tabindex="0"><thead><tr><th>Desktop</th><th>Packages or groups</th><th>Display manager</th></tr></thead><tbody><tr><td><a href="https://wiki.archlinux.org/title/GNOME" target="_blank" rel="noreferrer">GNOME</a></td><td><code>gnome</code> (<code>gnome-extra</code> optional)</td><td><code>gdm</code>; enable <code>gdm.service</code></td></tr><tr><td><a href="https://wiki.archlinux.org/title/Xfce" target="_blank" rel="noreferrer">Xfce</a></td><td><code>xorg-server xfce4 xfce4-goodies</code></td><td>LightDM, below</td></tr><tr><td><a href="https://wiki.archlinux.org/title/LXDE" target="_blank" rel="noreferrer">LXDE</a></td><td><code>xorg-server lxde lxdm</code></td><td>Enable <code>lxdm.service</code></td></tr><tr><td><a href="https://wiki.archlinux.org/title/LXQt" target="_blank" rel="noreferrer">LXQt</a></td><td><code>xorg-server lxqt breeze-icons sddm</code></td><td>Enable <code>sddm.service</code>; see the wiki for the separate Wayland setup</td></tr><tr><td><a href="https://wiki.archlinux.org/title/Cinnamon" target="_blank" rel="noreferrer">Cinnamon</a></td><td><code>xorg-server cinnamon xed xreader gnome-terminal</code></td><td>LightDM, below</td></tr><tr><td><a href="https://wiki.archlinux.org/title/Budgie" target="_blank" rel="noreferrer">Budgie</a></td><td><code>budgie gdm</code></td><td>Enable <code>gdm.service</code>; current Budgie uses Wayland</td></tr><tr><td><a href="https://wiki.archlinux.org/title/MATE" target="_blank" rel="noreferrer">MATE</a></td><td><code>xorg-server mate mate-extra</code></td><td>LightDM, below</td></tr><tr><td><a href="https://wiki.archlinux.org/title/Deepin" target="_blank" rel="noreferrer">Deepin</a></td><td><code>deepin deepin-extra</code></td><td>Follow its wiki&#39;s LightDM and greeter configuration</td></tr></tbody></table><p>For rows using LightDM:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lightdm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lightdm-gtk-greeter</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/lightdm/lightdm.conf</span></span></code></pre></div><p>Set <code>greeter-session=lightdm-gtk-greeter</code> in the <code>[Seat:*]</code> section, then enable the service:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lightdm.service</span></span></code></pre></div><p>Xorg normally uses the modesetting driver and libinput. Do not install every graphics driver or legacy input driver. Wayland desktops provide their own compositor; installing the <code>wayland</code> package alone does not create a desktop session.</p>`,16)])])}const g=t(n,[["render",r]]);export{k as __pageData,g as default};
